import 'package:flutter/material.dart';\nimport 'package:shared_preferences/shared_preferences.dart';\n\nclass BluetoothSettings {\n  bool enabled;\n  bool showNotification;\n  bool resumeOnConnect;\n  bool pauseOnDisconnect;\n  int mediaButtonBehavior; // 0=single-tap play, 1=double-tap skip, etc\n\n  BluetoothSettings({\n    this.enabled = true,\n    this.showNotification = true,\n    this.resumeOnConnect = false,\n    this.pauseOnDisconnect = false,\n    this.mediaButtonBehavior = 0,\n  });\n\n  Map<String, dynamic> toMap() {\n    return {\n      'enabled': enabled,\n      'showNotification': showNotification,\n      'resumeOnConnect': resumeOnConnect,\n      'pauseOnDisconnect': pauseOnDisconnect,\n      'mediaButtonBehavior': mediaButtonBehavior,\n    };\n  }\n\n  factory BluetoothSettings.fromMap(Map<String, dynamic> map) {\n    return BluetoothSettings(\n      enabled: map['enabled'] ?? true,\n      showNotification: map['showNotification'] ?? true,\n      resumeOnConnect: map['resumeOnConnect'] ?? false,\n      pauseOnDisconnect: map['pauseOnDisconnect'] ?? false,\n      mediaButtonBehavior: map['mediaButtonBehavior'] ?? 0,\n    );\n  }\n}\n\nclass BluetoothProvider extends ChangeNotifier {\n  late BluetoothSettings _settings;\n  bool _bluetoothConnected = false;\n  String _connectedDeviceName = '';\n  int _buttonPressCount = 0;\n  DateTime _lastButtonPress = DateTime.now();\n\n  // Getters\n  BluetoothSettings get settings => _settings;\n  bool get bluetoothConnected => _bluetoothConnected;\n  String get connectedDeviceName => _connectedDeviceName;\n  bool get isEnabled => _settings.enabled;\n  bool get showNotification => _settings.showNotification;\n  bool get resumeOnConnect => _settings.resumeOnConnect;\n  bool get pauseOnDisconnect => _settings.pauseOnDisconnect;\n\n  BluetoothProvider() {\n    _settings = BluetoothSettings();\n    _loadBluetoothSettings();\n    _initializeBluetoothListeners();\n  }\n\n  Future<void> _loadBluetoothSettings() async {\n    try {\n      final prefs = await SharedPreferences.getInstance();\n      \n      final enabled = prefs.getBool('bt_enabled') ?? true;\n      final showNotification = prefs.getBool('bt_show_notification') ?? true;\n      final resumeOnConnect = prefs.getBool('bt_resume_on_connect') ?? false;\n      final pauseOnDisconnect = prefs.getBool('bt_pause_on_disconnect') ?? false;\n      final mediaButtonBehavior = prefs.getInt('bt_button_behavior') ?? 0;\n\n      _settings = BluetoothSettings(\n        enabled: enabled,\n        showNotification: showNotification,\n        resumeOnConnect: resumeOnConnect,\n        pauseOnDisconnect: pauseOnDisconnect,\n        mediaButtonBehavior: mediaButtonBehavior,\n      );\n\n      notifyListeners();\n    } catch (e) {\n      print('Error loading bluetooth settings: $e');\n    }\n  }\n\n  Future<void> _saveBluetoothSettings() async {\n    try {\n      final prefs = await SharedPreferences.getInstance();\n      \n      await prefs.setBool('bt_enabled', _settings.enabled);\n      await prefs.setBool('bt_show_notification', _settings.showNotification);\n      await prefs.setBool('bt_resume_on_connect', _settings.resumeOnConnect);\n      await prefs.setBool('bt_pause_on_disconnect', _settings.pauseOnDisconnect);\n      await prefs.setInt('bt_button_behavior', _settings.mediaButtonBehavior);\n    } catch (e) {\n      print('Error saving bluetooth settings: $e');\n    }\n  }\n\n  void _initializeBluetoothListeners() {\n    // This would integrate with actual Bluetooth service\n    // For now, simulating Bluetooth state\n    print('Bluetooth listeners initialized');\n  }\n\n  // Toggle Bluetooth support\n  Future<void> toggleBluetooth(bool enabled) async {\n    _settings.enabled = enabled;\n    await _saveBluetoothSettings();\n    notifyListeners();\n  }\n\n  // Toggle notification\n  Future<void> toggleNotification(bool show) async {\n    _settings.showNotification = show;\n    await _saveBluetoothSettings();\n    notifyListeners();\n  }\n\n  // Toggle resume on connect\n  Future<void> toggleResumeOnConnect(bool enabled) async {\n    _settings.resumeOnConnect = enabled;\n    await _saveBluetoothSettings();\n    notifyListeners();\n  }\n\n  // Toggle pause on disconnect\n  Future<void> togglePauseOnDisconnect(bool enabled) async {\n    _settings.pauseOnDisconnect = enabled;\n    await _saveBluetoothSettings();\n    notifyListeners();\n  }\n\n  // Set media button behavior\n  Future<void> setMediaButtonBehavior(int behavior) async {\n    _settings.mediaButtonBehavior = behavior;\n    await _saveBluetoothSettings();\n    notifyListeners();\n  }\n\n  // Handle Bluetooth connection\n  void handleBluetoothConnected(String deviceName) {\n    _bluetoothConnected = true;\n    _connectedDeviceName = deviceName;\n    print('Bluetooth connected: $deviceName');\n    notifyListeners();\n  }\n\n  // Handle Bluetooth disconnection\n  void handleBluetoothDisconnected() {\n    _bluetoothConnected = false;\n    _connectedDeviceName = '';\n    print('Bluetooth disconnected');\n    notifyListeners();\n  }\n\n  // Handle headphone button press\n  // Returns the action to perform: 'play_pause', 'next', 'previous'\n  String handleMediaButtonPress() {\n    final now = DateTime.now();\n    final timeSinceLastPress = now.difference(_lastButtonPress).inMilliseconds;\n\n    // If more than 300ms since last press, reset count\n    if (timeSinceLastPress > 300) {\n      _buttonPressCount = 1;\n    } else {\n      _buttonPressCount++;\n    }\n\n    _lastButtonPress = now;\n\n    // Behavior based on settings and button press count\n    switch (_settings.mediaButtonBehavior) {\n      case 0: // Single tap: play/pause, Double: next, Triple: previous\n        if (_buttonPressCount == 1) {\n          return 'play_pause';\n        } else if (_buttonPressCount == 2) {\n          return 'next';\n        } else if (_buttonPressCount >= 3) {\n          _buttonPressCount = 0;\n          return 'previous';\n        }\n        return 'play_pause';\n      case 1: // Always play/pause\n        return 'play_pause';\n      case 2: // Always next\n        return 'next';\n      default:\n        return 'play_pause';\n    }\n  }\n\n  // Get button behavior description\n  String getButtonBehaviorDescription(int behavior) {\n    switch (behavior) {\n      case 0:\n        return 'Single tap: Play/Pause, Double: Next, Triple: Previous';\n      case 1:\n        return 'Always Play/Pause';\n      case 2:\n        return 'Always Next';\n      default:\n        return 'Unknown';\n    }\n  }\n\n  // Get connected device info\n  String getConnectionStatus() {\n    if (!_bluetoothConnected) {\n      return 'No device connected';\n    }\n    return 'Connected to $_connectedDeviceName';\n  }\n}\n